/*
  PocketTube - ESP32 Dev Module
  Hardware wiring used by this sketch:
    ST7789 TFT: SCK=18, MOSI=23, DC=22, CS=5, RST=4, BLK=3V3
    ES8311: MCLK=1, BCLK=26, WS=25, DIN=27, SCL=19, SDA=21, PA_EN=32
    Joystick: VRx=34, VRy=35, SW=33
    Volume buttons: UP=13, DOWN=14

  Assumptions:
    - Classic ESP32 (not ESP32-S3)
    - 240x320 ST7789-compatible TFT
    - LAFVIN audio board really uses ES8311 at I2C address 0x18
    - Server provides:
        GET /search?q=trending       -> plain text: videoId|title per line
        GET /stream_video?id=...    -> raw RGB565 big-endian, 240x160 frames
        GET /stream_audio?id=...    -> raw signed 16-bit little-endian mono PCM, 16 kHz

  Install only the LovyanGFX library.
  Select "ESP32 Dev Module" and use Arduino-ESP32 core 2.x for this
  legacy I2S driver version.
*/

#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <SPI.h>
#include <LovyanGFX.hpp>
#include <driver/i2s.h>
#include <Wire.h>

// ---------------- Wi-Fi / server ----------------
const char* WIFI_SSID = "tuonela";
const char* WIFI_PASSWORD = "C@tfish1";
const char* SERVER_URL = "https://pockettube-server-2.onrender.com";

// ---------------- Display pins ------------------
#define TFT_SCLK 18
#define TFT_MOSI 23
#define TFT_MISO -1
#define TFT_CS    5
#define TFT_DC   22
#define TFT_RST   4

// ---------------- ES8311 / I2S pins -------------
#define I2S_MCLK  1
#define I2S_BCLK 26
#define I2S_WS   25
#define I2S_DOUT 27
#define ES8311_SDA 21
#define ES8311_SCL 19
#define PA_ENABLE 32
#define ES8311_ADDR 0x18

// ---------------- Controls -----------------------
#define JOY_X_PIN 34
#define JOY_Y_PIN 35
#define JOY_SW_PIN 33
#define VOL_UP_PIN 13
#define VOL_DOWN_PIN 14

// ---------------- Video settings -----------------
static const int SCREEN_W = 240;
static const int SCREEN_H = 320;
static const int VIDEO_W = 240;
static const int VIDEO_H = 160;
static const size_t FRAME_BYTES = VIDEO_W * VIDEO_H * 2;
static const uint32_t AUDIO_RATE = 16000;
static const int MAX_VIDEOS = 10;

class LGFX : public lgfx::LGFX_Device {
  lgfx::Panel_ST7789 _panel;
  lgfx::Bus_SPI _bus;

public:
  LGFX() {
    {
      auto cfg = _bus.config();
      cfg.spi_host = SPI2_HOST;
      cfg.spi_mode = 0;
      cfg.freq_write = 40000000;
      cfg.freq_read = 16000000;
      cfg.spi_3wire = false;
      cfg.use_lock = true;
      cfg.dma_channel = SPI_DMA_CH_AUTO;
      cfg.pin_sclk = TFT_SCLK;
      cfg.pin_mosi = TFT_MOSI;
      cfg.pin_miso = TFT_MISO;
      cfg.pin_dc = TFT_DC;
      _bus.config(cfg);
      _panel.setBus(&_bus);
    }
    {
      auto cfg = _panel.config();
      cfg.pin_cs = TFT_CS;
      cfg.pin_rst = TFT_RST;
      cfg.pin_busy = -1;
      cfg.panel_width = SCREEN_W;
      cfg.panel_height = SCREEN_H;
      cfg.offset_x = 0;
      cfg.offset_y = 0;
      cfg.invert = true;
      cfg.rgb_order = false;
      _panel.config(cfg);
    }
    setPanel(&_panel);
  }
};

LGFX tft;

String videoIds[MAX_VIDEOS];
String videoTitles[MAX_VIDEOS];
int videoCount = 0;
int selectedIndex = 0;

volatile bool isPlaying = false;
volatile float volumeGain = 0.55f;
volatile bool audioTaskRunning = false;

struct AudioTaskArgs {
  char videoId[20];
};

// ---------------- Small helpers ------------------
String makeUrl(const String& path) {
  String base = SERVER_URL;
  while (base.endsWith("/")) base.remove(base.length() - 1);
  return base + path;
}

String urlEncode(const String& value) {
  String out;
  const char* hex = "0123456789ABCDEF";
  for (size_t i = 0; i < value.length(); ++i) {
    uint8_t c = (uint8_t)value[i];
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9') || c == '-' || c == '_' ||
        c == '.' || c == '~') {
      out += (char)c;
    } else if (c == ' ') {
      out += "%20";
    } else {
      out += '%';
      out += hex[c >> 4];
      out += hex[c & 0x0F];
    }
  }
  return out;
}

void showMessage(const String& line1, const String& line2 = "") {
  tft.fillScreen(TFT_BLACK);
  tft.setTextDatum(textdatum_t::top_left);
  tft.setTextColor(TFT_WHITE, TFT_BLACK);
  tft.setTextSize(2);
  tft.drawString(line1, 10, 110);
  tft.setTextSize(1);
  if (line2.length()) tft.drawString(line2, 10, 145);
}

bool buttonPressed(uint8_t pin) {
  if (digitalRead(pin) == LOW) {
    delay(25);
    return digitalRead(pin) == LOW;
  }
  return false;
}

// ---------------- ES8311 I2C ---------------------
bool codecWrite(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(ES8311_ADDR);
  Wire.write(reg);
  Wire.write(value);
  return Wire.endTransmission() == 0;
}

bool codecProbe() {
  Wire.beginTransmission(ES8311_ADDR);
  return Wire.endTransmission() == 0;
}

bool initES8311() {
  if (!codecProbe()) return false;

  // ES8311 16 kHz, 16-bit I2S playback initialization.
  // MCLK is supplied by the ESP32 I2S peripheral on GPIO1.
  codecWrite(0x00, 0x1F);
  delay(20);
  codecWrite(0x00, 0x00);
  codecWrite(0x01, 0x3F);
  codecWrite(0x02, 0x08);
  codecWrite(0x03, 0x10);
  codecWrite(0x04, 0x10);
  codecWrite(0x05, 0x00);
  codecWrite(0x06, 0x03);
  codecWrite(0x07, 0x00);
  codecWrite(0x08, 0xFF);
  codecWrite(0x09, 0x0C);  // 16-bit I2S input to DAC
  codecWrite(0x0A, 0x0C);
  codecWrite(0x0D, 0x01);
  codecWrite(0x0E, 0x02);
  codecWrite(0x12, 0x00);
  codecWrite(0x13, 0x10);
  codecWrite(0x14, 0x1A);
  codecWrite(0x1B, 0x0A);
  codecWrite(0x1C, 0x6A);
  codecWrite(0x37, 0x08);
  codecWrite(0x44, 0x08);
  codecWrite(0x44, 0x58);
  codecWrite(0x32, 0xBF);  // DAC digital volume
  codecWrite(0x31, 0x00);  // Unmute DAC
  delay(30);
  return true;
}

// ---------------- I2S playback -------------------
bool initI2S() {
  i2s_config_t cfg = {};
  cfg.mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX);
  cfg.sample_rate = AUDIO_RATE;
  cfg.bits_per_sample = I2S_BITS_PER_SAMPLE_16BIT;
  cfg.channel_format = I2S_CHANNEL_FMT_RIGHT_LEFT;
  cfg.communication_format = I2S_COMM_FORMAT_STAND_I2S;
  cfg.intr_alloc_flags = ESP_INTR_FLAG_LEVEL1;
  cfg.dma_buf_count = 8;
  cfg.dma_buf_len = 256;
  cfg.use_apll = false;
  cfg.tx_desc_auto_clear = true;
  cfg.fixed_mclk = AUDIO_RATE * 256;

  esp_err_t err = i2s_driver_install(I2S_NUM_0, &cfg, 0, NULL);
  if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) return false;

  i2s_pin_config_t pins = {};
  pins.mck_io_num = I2S_MCLK;
  pins.bck_io_num = I2S_BCLK;
  pins.ws_io_num = I2S_WS;
  pins.data_out_num = I2S_DOUT;
  pins.data_in_num = I2S_PIN_NO_CHANGE;

  err = i2s_set_pin(I2S_NUM_0, &pins);
  if (err != ESP_OK) return false;
  i2s_set_clk(I2S_NUM_0, AUDIO_RATE, I2S_BITS_PER_SAMPLE_16BIT,
              I2S_CHANNEL_STEREO);
  return true;
}

void audioTask(void* parameter) {
  AudioTaskArgs* args = (AudioTaskArgs*)parameter;
  char videoId[20];
  strncpy(videoId, args->videoId, sizeof(videoId));
  videoId[sizeof(videoId) - 1] = '\0';
  delete args;

  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  HTTPClient http;
  http.setTimeout(20000);
  String url = makeUrl(String("/stream_audio?id=") + videoId);

  if (http.begin(client, url) && http.GET() == HTTP_CODE_OK) {
    WiFiClient* stream = http.getStreamPtr();
    uint8_t monoBytes[1024];
    int16_t stereoSamples[1024]; // 512 mono samples -> 1024 stereo samples

    while (isPlaying && http.connected()) {
      int available = stream->available();
      if (available <= 0) {
        vTaskDelay(2);
        continue;
      }

      int wanted = available;
      if (wanted > (int)sizeof(monoBytes)) wanted = sizeof(monoBytes);
      wanted &= ~1; // complete 16-bit samples only
      if (wanted <= 0) continue;

      int got = stream->read(monoBytes, wanted);
      if (got <= 0) {
        vTaskDelay(2);
        continue;
      }
      got &= ~1;

      int sampleCount = got / 2;
      for (int i = 0; i < sampleCount; ++i) {
        int16_t sample = (int16_t)((uint16_t)monoBytes[i * 2] |
                                  ((uint16_t)monoBytes[i * 2 + 1] << 8));
        int32_t scaled = (int32_t)(sample * volumeGain);
        if (scaled > 32767) scaled = 32767;
        if (scaled < -32768) scaled = -32768;
        stereoSamples[i * 2] = (int16_t)scaled;
        stereoSamples[i * 2 + 1] = (int16_t)scaled;
      }

      size_t written = 0;
      i2s_write(I2S_NUM_0, stereoSamples,
                sampleCount * 2 * sizeof(int16_t),
                &written, pdMS_TO_TICKS(500));
    }
  }

  http.end();
  audioTaskRunning = false;
  vTaskDelete(NULL);
}

// ---------------- Feed / menu -------------------
void fetchFeed(const String& query) {
  videoCount = 0;
  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  HTTPClient http;
  http.setTimeout(30000);
  String url = makeUrl(String("/search?q=") + urlEncode(query));

  if (!http.begin(client, url)) return;
  int status = http.GET();

  if (status == HTTP_CODE_OK) {
    String body = http.getString();
    int start = 0;

    while (start < body.length() && videoCount < MAX_VIDEOS) {
      int end = body.indexOf('\n', start);
      if (end < 0) end = body.length();

      String line = body.substring(start, end);
      line.trim();
      int separator = line.indexOf('|');

      if (separator > 0) {
        videoIds[videoCount] = line.substring(0, separator);
        videoTitles[videoCount] = line.substring(separator + 1);
        videoTitles[videoCount].replace('\r', ' ');
        videoCount++;
      }
      start = end + 1;
    }
  }
  http.end();
  selectedIndex = 0;
}

void drawMenu() {
  tft.fillScreen(TFT_BLACK);
  tft.setTextDatum(textdatum_t::top_left);
  tft.fillRect(0, 0, SCREEN_W, 34, TFT_DARKGREY);
  tft.setTextColor(TFT_RED, TFT_DARKGREY);
  tft.setTextSize(2);
  tft.drawString("PocketTube", 8, 7);

  tft.setTextSize(1);
  tft.setTextColor(TFT_LIGHTGREY, TFT_BLACK);
  tft.drawString("UP/DOWN: browse   PRESS: play", 8, 40);

  if (videoCount == 0) {
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.drawString("No videos returned.", 10, 90);
    tft.drawString("Check the server /search route.", 10, 108);
    return;
  }

  for (int i = 0; i < videoCount; ++i) {
    int y = 62 + i * 24;
    uint16_t bg = (i == selectedIndex) ? TFT_RED : TFT_BLACK;
    uint16_t fg = TFT_WHITE;
    tft.fillRoundRect(5, y, 230, 21, 3, bg);
    tft.setTextColor(fg, bg);
    String title = videoTitles[i];
    if (title.length() > 34) title = title.substring(0, 34);
    tft.drawString(title, 10, y + 6);
  }

  tft.setTextColor(TFT_LIGHTGREY, TFT_BLACK);
  tft.drawString("VOL buttons: adjust speaker volume", 8, 310);
}

// ---------------- Video playback -----------------
bool readExact(WiFiClient* stream, uint8_t* destination,
               size_t length, uint32_t timeoutMs) {
  size_t received = 0;
  uint32_t lastData = millis();

  while (received < length && isPlaying) {
    int available = stream->available();
    if (available > 0) {
      size_t amount = (size_t)available;
      if (amount > length - received) amount = length - received;
      int got = stream->read(destination + received, amount);
      if (got > 0) {
        received += (size_t)got;
        lastData = millis();
      }
    } else {
      if (!stream->connected()) break;
      if (millis() - lastData > timeoutMs) break;
      vTaskDelay(1);
    }

    if (buttonPressed(JOY_SW_PIN)) {
      isPlaying = false;
      break;
    }
    if (buttonPressed(VOL_UP_PIN)) {
      volumeGain += 0.08f;
      if (volumeGain > 1.0f) volumeGain = 1.0f;
    }
    if (buttonPressed(VOL_DOWN_PIN)) {
      volumeGain -= 0.08f;
      if (volumeGain < 0.0f) volumeGain = 0.0f;
    }
  }
  return received == length;
}

void playVideo(const String& videoId, const String& title) {
  if (videoId.length() == 0) return;

  isPlaying = true;
  showMessage("Loading video...", title.substring(0, 28));

  AudioTaskArgs* args = new AudioTaskArgs();
  memset(args, 0, sizeof(AudioTaskArgs));
  videoId.toCharArray(args->videoId, sizeof(args->videoId));

  audioTaskRunning = true;
  BaseType_t taskCreated = xTaskCreatePinnedToCore(
    audioTask, "AudioStream", 8192, args, 2, NULL, 0
  );
  if (taskCreated != pdPASS) {
    delete args;
    audioTaskRunning = false;
  }

  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  HTTPClient http;
  http.setTimeout(20000);
  String url = makeUrl(String("/stream_video?id=") + videoId);

  uint8_t* frame = (uint8_t*)heap_caps_malloc(
    FRAME_BYTES, MALLOC_CAP_8BIT
  );
  if (!frame) frame = (uint8_t*)malloc(FRAME_BYTES);

  if (!frame) {
    isPlaying = false;
    http.end();
    showMessage("Not enough memory", "Could not allocate frame");
    delay(1500);
    drawMenu();
    return;
  }

  if (http.begin(client, url) && http.GET() == HTTP_CODE_OK) {
    WiFiClient* stream = http.getStreamPtr();

    tft.fillScreen(TFT_BLACK);
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(1);
    tft.drawString("PocketTube  |  PRESS to stop", 5, 5);
    tft.drawRect(0, 22, VIDEO_W, VIDEO_H + 2, TFT_DARKGREY);
    tft.drawString(title.substring(0, 36), 5, 194);
    tft.drawString("Volume +/- buttons", 5, 214);

    while (isPlaying && stream->connected()) {
      if (!readExact(stream, frame, FRAME_BYTES, 12000)) break;

      // Server sends RGB565 big-endian pixels. LovyanGFX expects RGB565.
      uint16_t* pixels = (uint16_t*)frame;
      for (size_t i = 0; i < FRAME_BYTES / 2; ++i) {
        pixels[i] = (uint16_t)((pixels[i] >> 8) | (pixels[i] << 8));
      }
      tft.pushImage(0, 24, VIDEO_W, VIDEO_H, pixels);
    }
  } else {
    showMessage("Video stream failed", "Check server endpoint");
    delay(1500);
  }

  isPlaying = false;
  http.end();
  if (frame) free(frame);

  uint32_t waitStart = millis();
  while (audioTaskRunning && millis() - waitStart < 2500) delay(10);
  i2s_zero_dma_buffer(I2S_NUM_0);
  drawMenu();
}

// ---------------- Setup / main loop --------------
void setup() {
  Serial.begin(115200);

  pinMode(JOY_SW_PIN, INPUT_PULLUP);
  pinMode(VOL_UP_PIN, INPUT_PULLUP);
  pinMode(VOL_DOWN_PIN, INPUT_PULLUP);
  pinMode(PA_ENABLE, OUTPUT);
  digitalWrite(PA_ENABLE, LOW); // amplifier disabled during initialization

  analogReadResolution(12);
  analogSetPinAttenuation(JOY_X_PIN, ADC_11db);
  analogSetPinAttenuation(JOY_Y_PIN, ADC_11db);

  tft.init();
  tft.setRotation(0);
  tft.setColorDepth(16);
  tft.fillScreen(TFT_BLACK);

  Wire.begin(ES8311_SDA, ES8311_SCL);
  Wire.setClock(100000);

  showMessage("Starting audio...", "Initializing I2S / ES8311");
  bool i2sOK = initI2S();
  delay(50);
  bool codecOK = initES8311();

  if (i2sOK && codecOK) {
    digitalWrite(PA_ENABLE, HIGH);
  } else {
    Serial.printf("Audio init: I2S=%d ES8311=%d\n", i2sOK, codecOK);
  }

  showMessage("Connecting Wi-Fi...", WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  uint32_t wifiStart = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - wifiStart < 25000) {
    delay(250);
  }

  if (WiFi.status() != WL_CONNECTED) {
    showMessage("Wi-Fi failed", "Check SSID/password");
    return;
  }

  showMessage("Waking server...", "Render may need 45 seconds");
  fetchFeed("trending");
  drawMenu();
}

void loop() {
  if (WiFi.status() != WL_CONNECTED || videoCount == 0) {
    delay(250);
    return;
  }

  int xValue = analogRead(JOY_X_PIN);
  int yValue = analogRead(JOY_Y_PIN);

  // Most joystick modules rest near 2048. Change these thresholds
  // if your particular joystick has a different center/dead zone.
  if (yValue < 900 && selectedIndex > 0) {
    selectedIndex--;
    drawMenu();
    delay(220);
  } else if (yValue > 3200 && selectedIndex < videoCount - 1) {
    selectedIndex++;
    drawMenu();
    delay(220);
  }

  // X axis is read as well so its wiring is verified and available
  // for later horizontal menu actions. It is intentionally not used
  // to change the selected video in this vertical list.
  (void)xValue;

  if (buttonPressed(JOY_SW_PIN)) {
    delay(180);
    playVideo(videoIds[selectedIndex], videoTitles[selectedIndex]);
    while (digitalRead(JOY_SW_PIN) == LOW) delay(10);
  }

  if (buttonPressed(VOL_UP_PIN)) {
    volumeGain += 0.08f;
    if (volumeGain > 1.0f) volumeGain = 1.0f;
    delay(120);
  }
  if (buttonPressed(VOL_DOWN_PIN)) {
    volumeGain -= 0.08f;
    if (volumeGain < 0.0f) volumeGain = 0.0f;
    delay(120);
  }

  delay(10);
}
